## 第一部分：MCP（Model Context Protocol）深度

### MCP 架构

```
MCP 三层架构：
┌─────────────────────────────────────────────────────────────────────┐
│  Transport 层（传输层）                                               │
│  • STDIO: 本地进程通信                                               │
│  • HTTP: 远程 HTTP 通信                                              │
│  • SSE: 服务端发送事件（Server-Sent Events）                          │
│                                                                     │
│  Protocol 层（协议层）                                               │
│  • Initialize: 握手协商                                             │
│  • Tools: 工具调用（List/Call）                                      │
│  • Resources: 资源访问                                               │
│  • Prompts: 提示词模板                                               │
│  • Sampling: LLM 采样                                                │
│                                                                     │
│  Implementation 层（实现层）                                          │
│  • Server: 暴露工具/资源/提示词                                      │
│  • Client: 调用工具/资源/提示词                                     │
│  • Host: 管理 MCP 生命周期（Hermes/Claude Desktop）                  │
└─────────────────────────────────────────────────────────────────────┘
```

### MCP Server 实现

```go
package mcp

import (
	"context"
	"encoding/json"
	"fmt"
	"net"
	"sync"
)

// MCPRequest MCP 请求
type MCPRequest struct {
	JSONRPC string          `json:"jsonrpc"`
	ID      json.RawMessage `json:"id"`
	Method  string          `json:"method"`
	Params  json.RawMessage `json:"params,omitempty"`
}

// MCPResponse MCP 响应
type MCPResponse struct {
	JSONRPC string      `json:"jsonrpc"`
	ID      json.RawMessage `json:"id"`
	Result  interface{} `json:"result,omitempty"`
	Error   *MCPError   `json:"error,omitempty"`
}

type MCPError struct {
	Code    int    `json:"code"`
	Message string `json:"message"`
}

// Tool MCP 工具
type Tool struct {
	Name        string          `json:"name"`
	Description string          `json:"description"`
	InputSchema json.RawMessage `json:"inputSchema"`
	Handler     func(context.Context, json.RawMessage) (interface{}, error)
}

// Resource MCP 资源
type Resource struct {
	URI         string          `json:"uri"`
	Name        string          `json:"name"`
	Description string          `json:"description"`
	MimeType    string          `json:"mimeType"`
	Read        func(context.Context) (string, error)
}

// MCPServer MCP 服务器
type MCPServer struct {
	version     string
	tools       map[string]*Tool
	resources   map[string]*Resource
	mu          sync.RWMutex
}

// NewMCPServer 创建 MCP 服务器
func NewMCPServer(version string) *MCPServer {
	return &MCPServer{
		version: version,
		tools:   make(map[string]*Tool),
		resources: make(map[string]*Resource),
	}
}

// AddTool 添加工具
func (s *MCPServer) AddTool(tool *Tool) {
	s.mu.Lock()
	defer s.mu.Unlock()
	s.tools[tool.Name] = tool
}

// AddResource 添加资源
func (s *MCPServer) AddResource(resource *Resource) {
	s.mu.Lock()
	defer s.mu.Unlock()
	s.resources[resource.URI] = resource
}

// HandleRequest 处理请求
func (s *MCPServer) HandleRequest(ctx context.Context, req MCPRequest) (*MCPResponse, error) {
	var resp MCPResponse
	resp.JSONRPC = "2.0"
	resp.ID = req.ID

	switch req.Method {
	case "initialize":
		result := map[string]interface{}{
			"protocolVersion": "2024-11-05",
			"serverInfo": map[string]string{
				"name":    "ad-platform-mcp",
				"version": s.version,
			},
			"capabilities": map[string]interface{}{
				"tools": map[string]interface{}{},
				"resources": map[string]interface{}{},
			},
		}
		resp.Result = result

	case "tools/list":
		tools := make([]map[string]interface{}, 0, len(s.tools))
		for name, tool := range s.tools {
			tools = append(tools, map[string]interface{}{
				"name":        name,
				"description": tool.Description,
				"inputSchema": json.RawMessage(tool.InputSchema),
			})
		}
		resp.Result = map[string]interface{}{"tools": tools}

	case "tools/call":
		var params struct {
			Name   string          `json:"name"`
			Args   json.RawMessage `json:"arguments"`
		}
		json.Unmarshal(req.Params, &params)

		tool, ok := s.tools[params.Name]
		if !ok {
			return &MCPResponse{
				JSONRPC: "2.0",
				ID:      req.ID,
				Error: &MCPError{
					Code:    -32601,
					Message: fmt.Sprintf("tool not found: %s", params.Name),
				},
			}, nil
		}

		result, err := tool.Handler(ctx, params.Args)
		if err != nil {
			return &MCPResponse{
				JSONRPC: "2.0",
				ID:      req.ID,
				Error: &MCPError{
					Code:    -32603,
					Message: err.Error(),
				},
			}, nil
		}

		resp.Result = result

	case "resources/list":
		resources := make([]map[string]interface{}, 0, len(s.resources))
		for uri, resource := range s.resources {
			resources = append(resources, map[string]interface{}{
				"uri":         uri,
				"name":        resource.Name,
				"description": resource.Description,
				"mimeType":    resource.MimeType,
			})
		}
		resp.Result = map[string]interface{}{"resources": resources}

	case "resources/read":
		var params struct {
			URI string `json:"uri"`
		}
		json.Unmarshal(req.Params, &params)

		resource, ok := s.resources[params.URI]
		if !ok {
			return &MCPResponse{
				JSONRPC: "2.0",
				ID:      req.ID,
				Error: &MCPError{
					Code:    -32602,
					Message: fmt.Sprintf("resource not found: %s", params.URI),
				},
			}, nil
		}

		content, err := resource.Read(ctx)
		if err != nil {
			return &MCPResponse{
				JSONRPC: "2.0",
				ID:      req.ID,
				Error: &MCPError{
					Code:    -32603,
					Message: err.Error(),
				},
			}, nil
		}

		resp.Result = map[string]interface{}{
			"contents": []map[string]interface{}{
				{"uri": params.URI, "text": content},
			},
		}

	default:
		return &MCPResponse{
			JSONRPC: "2.0",
			ID:      req.ID,
			Error: &MCPError{
				Code:    -32601,
				Message: fmt.Sprintf("method not found: %s", req.Method),
			},
		}, nil
	}

	return &resp, nil
}

// StartHTTPServer 启动 HTTP 服务器
func (s *MCPServer) StartHTTPServer(addr string) error {
	listener, err := net.Listen("tcp", addr)
	if err != nil {
		return err
	}

	http.HandleFunc("/mcp", func(w http.ResponseWriter, r *http.Request) {
		if r.Method != http.MethodPost {
			http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
			return
		}

		var req MCPRequest
		if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
			http.Error(w, err.Error(), http.StatusBadRequest)
			return
		}

		ctx := r.Context()
		resp, err := s.HandleRequest(ctx, req)
		if err != nil {
			http.Error(w, err.Error(), http.StatusInternalServerError)
			return
		}

		w.Header().Set("Content-Type", "application/json")
		json.NewEncoder(w).Encode(resp)
	})

	return http.Serve(listener, nil)
}
```

