## 第三部分：图编排

```go
package orchestration

// Node 图节点
type Node struct {
	ID       string
	Type     string // tool/skill/router/condition
	Config   map[string]interface{}
	Next     []string
}

// Graph 编排图
type Graph struct {
	Nodes  map[string]*Node
	Start  string
	End    string
}

// Executor 执行器
type Executor struct {
	graph *Graph
	state map[string]interface{}
}

func (e *Executor) Execute(ctx context.Context) error {
	current := e.graph.Start

	for current != e.graph.End {
		node := e.graph.Nodes[current]

		// 执行节点
		result, err := e.executeNode(ctx, node)
		if err != nil {
			return err
		}

		// 更新状态
		e.state[node.ID] = result

		// 路由到下一个节点
		nextNode, err := e.route(ctx, node, result)
		if err != nil {
			return err
		}

		current = nextNode
	}

	return nil
}
```

