```go
package nl2ad

// NL2AD 自然语言创建广告
type NL2AD struct {
	llm        LLMClient
	policy     PolicyEngine
	templateDB TemplateDatabase
}

type Intent struct {
	Action    string
	Platform  string
	Campaign  string
	Budget    float64
	Targeting Targeting
	Creative  CreativeBrief
}

type Targeting struct {
	AgeRange  [2]int
	Genders   []string
	Locations []string
	Interests []string
}

type CreativeBrief struct {
	Title       string
	Description string
	VisualStyle string
	CTA         string
	BrandTone   string
}

func (n *NL2AD) ParseIntent(ctx context.Context, userInput string) (*Intent, error) {
	prompt := fmt.Sprintf(`
解析以下自然语言请求为结构化数据:
%s

返回 JSON:
{
  "action": "create|update|optimize",
  "platform": "facebook|google|tiktok",
  "campaign": "广告系列名称",
  "budget": 预算金额,
  "targeting": {
    "age_range": [最小年龄, 最大年龄],
    "genders": ["gender1"],
    "locations": ["country_code"],
    "interests": ["interest1"]
  },
  "creative": {
    "title": "标题",
    "description": "描述",
    "visual_style": "minimalist|colorful|lifestyle",
    "cta": "shop_now|learn_more",
    "brand_tone": "professional|casual|fun"
  }
}`, userInput)

	response, err := n.llm.Generate(ctx, prompt)
	if err != nil {
		return nil, err
	}

	intent := &Intent{}
	json.Unmarshal([]byte(response), intent)
	return intent, nil
}
