## 第二部分：Jenkins Pipeline 源码

```groovy
// Jenkinsfile：广告平台 CI/CD 流水线
pipeline {
    agent {
        kubernetes {
            yaml """
            apiVersion: v1
            kind: Pod
            spec:
              containers:
              - name: golang
                image: golang:1.21-alpine
                volumeMounts:
                - name: docker-sock
                  mountPath: /var/run/docker.sock
              volumes:
              - name: docker-sock
                hostPath:
                  path: /var/run/docker.sock
            """
        }
    }

    environment {
        REGISTRY = 'registry.cn-hangzhou.aliyuncs.com'
        IMAGE_NAME = 'ad-platform'
        VERSION = "${env.BUILD_NUMBER}"
    }

    stages {
        stage('Checkout') {
            steps {
                checkout scm
            }
        }

        stage('Lint') {
            steps {
                sh '''
                go vet ./...
                golangci-lint run ./...
                '''
            }
        }

        stage('Test') {
            steps {
                sh '''
                go test -race -coverprofile=coverage.out ./...
                go tool cover -func=coverage.out
                '''
            }
            post {
                success {
                    cobertura coveragePattern: 'coverage.out'
                }
            }
        }

        stage('Build') {
            steps {
                script {
                    // 1. 构建镜像
                    sh """
                    docker build -t ${REGISTRY}/${IMAGE_NAME}:${VERSION} .
                    docker tag ${REGISTRY}/${IMAGE_NAME}:${VERSION} \\
                        ${REGISTRY}/${IMAGE_NAME}:latest
                    """

                    // 2. 推送镜像
                    sh """
                    docker push ${REGISTRY}/${IMAGE_NAME}:${VERSION}
                    docker push ${REGISTRY}/${IMAGE_NAME}:latest
                    """
                }
            }
        }

        stage('Security Scan') {
            steps {
                sh '''
                trivy image ${REGISTRY}/${IMAGE_NAME}:${VERSION}
                '''
            }
        }

        stage('Deploy to Staging') {
            steps {
                script {
                    // 1. 更新 Helm values
                    sh """
                    helm upgrade --install ad-platform \\
                        ./charts/ad-platform \\
                        --namespace staging \\
                        --set image.tag=${VERSION} \\
                        --set image.registry=${REGISTRY} \\
                        --wait --timeout 300s
                    """
                }
            }
        }

        stage('Integration Test') {
            steps {
                sh '''
                ./scripts/integration-test.sh
                '''
            }
        }

        stage('Deploy to Production') {
            when {
                branch 'main'
            }
            steps {
                script {
                    // 1. 灰度发布（先 10%）
                    sh """
                    kubectl set image deployment/ad-platform \\
                        ad-platform=${REGISTRY}/${IMAGE_NAME}:${VERSION} \\
                        -n production
                    """

                    // 2. 等待健康检查
                    sh '''
                    sleep 60
                    kubectl rollout status deployment/ad-platform \\
                        -n production --timeout=300s
                    '''

                    // 3. 全量发布
                    sh '''
                    kubectl rollout restart deployment/ad-platform \\
                        -n production
                    '''
                }
            }
        }
    }

    post {
        always {
            // 清理工作空间
            cleanWs()
        }
        failure {
            // 发送通知
            slackSend(
                channel: '#dev-alerts',
                message: "❌ Build failed: ${env.BUILD_URL}"
            )
        }
        success {
            slackSend(
                channel: '#dev-alerts',
                message: "✅ Build succeeded: ${env.BUILD_URL}"
            )
        }
    }
}
```

