## 第三部分：ArgoCD 源码

```yaml
# ArgoCD Application：广告平台
apiVersion: argoproj.io/v1alpha1
kind: Application
metadata:
  name: ad-platform
  namespace: argocd
spec:
  project: default
  source:
    repoURL: https://github.com/ryan-myp/ad-platform-manifests.git
    targetRevision: main
    path: overlays/production
  destination:
    server: https://kubernetes.default.svc
    namespace: production
  syncPolicy:
    automated:
      prune: true  # 自动删除 Git 中不存在的资源
      selfHeal: true  # 自动修复漂移
    syncOptions:
      - CreateNamespace=true
      - PruneLast=true
  revisionHistoryLimit: 10
```

```yaml
# Kustomization：生产环境配置
apiVersion: kustomize.config.k8s.io/v1beta1
kind: Kustomization

namespace: production

resources:
  - ../../base

images:
  - name: ad-platform
    newName: registry.cn-hangzhou.aliyuncs.com/ad-platform
    newTag: "1.2.3"

patches:
  - path: replica-count.yaml
    target:
      kind: Deployment
      name: ad-platform

configMapGenerator:
  - name: ad-config
    literals:
      - AD_BUDGET_LIMIT=100000
      - ENABLE_DARK_MODE=true
```

```yaml
# base/deployment.yaml
apiVersion: apps/v1
kind: Deployment
metadata:
  name: ad-platform
  labels:
    app: ad-platform
spec:
  replicas: 3
  selector:
    matchLabels:
      app: ad-platform
  strategy:
    type: RollingUpdate
    rollingUpdate:
      maxSurge: 1
      maxUnavailable: 0
  template:
    metadata:
      labels:
        app: ad-platform
    spec:
      containers:
        - name: ad-platform
          image: registry.cn-hangzhou.aliyuncs.com/ad-platform:latest
          ports:
            - containerPort: 8080
          resources:
            requests:
              cpu: 500m
              memory: 512Mi
            limits:
              cpu: "1"
              memory: 1Gi
          readinessProbe:
            httpGet:
              path: /healthz
              port: 8080
            initialDelaySeconds: 5
            periodSeconds: 10
          livenessProbe:
            httpGet:
              path: /healthz
              port: 8080
            initialDelaySeconds: 15
            periodSeconds: 20
```

