	gae := t.ComputeGAE(observations, reward)

	// 2. 计算 policy loss
	policyLoss := t.ComputePolicyLoss(observations, gae)

	// 3. 更新策略
	t.Policy.Update(policyLoss)

	// 4. 更新价值模型
	valueLoss := t.ComputeValueLoss(observations, reward)
	t.RewardModel.Update(valueLoss)

	return nil
}
